    parts = urlparse(url)
    if parts.scheme != "https":
        raise PermissionError("only https is allowed")
    if parts.hostname not in ALLOWED_FETCH_HOSTS:
        raise PermissionError("host not allowed")
    return http_get(parts.hostname, parts.path or "/")[:200]

