def is_email(value: str) -> bool:
    if not value or len(value) > 254:
        return False
    # Simplified email regex to avoid catastrophic backtracking
    # Uses non-nested repetitions and avoids complex overlapping groups
    email_regex = re.compile(r"^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$")
    return bool(email_regex.match(value))


def is_slug(value: str) -> bool:
    if not value or len(value) > 255:
        return False
    # Slug regex: alphanumeric and hyphens only, no complex nesting
    slug_regex = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
