import urllib.parse
import socket
import ipaddress


def preview(url: str) -> str:
    validate_url(url)
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read().decode('utf-8')[:1000]
    except Exception as e:
        return f"Error fetching preview: {str(e)}"


def read_asset(url: str) -> str:
    validate_url(url)
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read().decode('utf-8')
    except Exception as e:
        return f"Error reading asset: {str(e)}"


def validate_url(url: str):
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        raise ValueError("Invalid scheme")
    if not parsed.hostname:
        raise ValueError("Invalid hostname")

    try:
        # Resolve hostname to IP to prevent DNS rebinding/bypass
        ip_address_str = socket.gethostbyname(parsed.hostname)
        ip = ipaddress.ip_address(ip_address_str)

        if ip.is_loopback or ip.is_private or ip.is_link_local or ip.is_multicast or ip.is_unspecified:
            raise PermissionError("Access to internal network is forbidden")
    except socket.gaierror:
        raise ValueError("Could not resolve hostname")
    except ValueError as e:
        if "Access to internal network" in str(e):
            raise
        raise ValueError("Invalid IP address")

