            return False
        if ip.is_private:
            return False
        if ip.is_link_local:
            return False
        if ip.is_multicast:
            return False
        if ip.is_unspecified:
            return False
        # Check for specific metadata service ranges if not covered
        if ip_address_str == '169.254.169.254':
            return False

        return True
    except Exception:
        return False

