"""Post-login redirects."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_REDIRECT_HOSTS


def safe_next(next_url: str) -> str:
    if not next_url:
        return "/home"

    parsed = urlparse(next_url)
    # If there is a scheme or a netloc, it's an absolute URL and potentially dangerous.
    # We only allow relative paths (where scheme and netloc are empty).
    if parsed.scheme or parsed.netloc:
        raise ValueError("Invalid redirect URL")

    # Ensure it starts with / to prevent protocol-relative URLs (e.g., //evil.com)
    if not next_url.startswith("/") or next_url.startswith("//"):
        raise ValueError("Invalid redirect URL")

    return next_url


def logout_target(next_url: str) -> str:
    return safe_next(next_url)

