from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent SSTI, we avoid using str.format() on user-provided templates.
    # Instead, we treat the template as a literal string and only perform simple replacement
    # of a specific placeholder, or we ensure no arbitrary attribute access can occur.
    # Here, we replace a specific placeholder '{name}' with the provided name.
    # This prevents the user from passing arbitrary format strings like '{user.__init__...}'
    # because we are not calling .format() on the template itself.
    return template.replace("{name}", name)

