from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent template injection via str.format, we ensure the template
    # only contains the specific allowed placeholder '{user}' and no other
    # formatting syntax that could be used for attribute traversal.
    if "{user}" not in template:
        raise ValueError("Invalid template")

    # Check for any other curly braces that might indicate an injection attempt
    # or complex formatting expressions.
    # A simple way to enforce safety is to only allow the exact string '{user}'
    # and nothing else that looks like a format expression.
    import re
    if re.search(r"\{(?!user\})", template):
        raise ValueError("Invalid template syntax")

    return template.format(user=User(name))

